    "videoUrl": "https://vimeo.com/640049239",
    "instructions": "1. Start with the feet at about shoulder width while holding each end of the stick. 2. Step to one side into a lateral lunge to load the hip. 3. When you hit the bottom of the lunge, stabilize the lower body, then rotate the torso in the direction of the leg you are stepping to. 4. At the bottom of your torso turn, your same side arm will be in the air and opposite arm down towards the floor. 5. Then drive out of the bottom, push off your back leg and rotate your torso in the opposite direction, swinging the body through and arms across like the top of a golf swing."
