    "instructions": "1. In a golf stance, position a stick horizontally at mid-torso height, and drive the base of the stick into a wall with a double-overhand grip. 2. For slightly less challenge, keep the elbows bent with the stick close to the body. 3. Push the stick hard into the wall with full body tension, not moving any area of the body. 4. Increase the challenge by slightly bending the elbows, and then finally going to a straight arm position. 5. Push and hold each rep for 3-6 seconds. 6. Complete the designated number of reps before switching sides."
