    "videoUrl": "https://vimeo.com/612232311",
    "instructions": "1. Position yourself in a 1/2 kneeling position but now open up the top leg as far as you can while keeping the chest and pelvis straight ahead. 2. Position your foot directly under the knee and tuck the pelvis and squeeze the glute of the down leg. 3. Place the stick vertically no more than 2 inches from the inside of the foot on the leg that has opened up. 4. Drive the stick down into the ground with the same side arm. 5. Work on laterally sliding the body towards the knee that is out to the side while keeping the heel down, working hip and ankle mobility. 6. You can also place the opposite arm out to the side with an open or closed fist to help create tension. 7. Complete 5 reps moving to the side, trying not to let the knee touch the stick. 8. On the 5th rep, hold at the bottom for 5 seconds at about 40-60% then drive back to the start position. 9. Switch sides and repeat this process on the other leg."
