    "instructions": "1. Position yourself in a shinbox position with one knee forward and one knee facing to the side. 2. The stick will be placed vertically into the ground in line with the midline of the thigh. 3. The hand that is on the same side of the forward leg will be vertical grabbing the top of the stick while the opposite hand will reach across and grab the stick right above the lower handle. 4. Push the stick into the ground and create an active hip hinge working to get long in the spine. 5. Perform 5 hip hinges, each time working to create length in the hip and spine. 6. On the 5th rep, get to your end range and lock it in and hold for 5 seconds while pushing down at 40-60%. 7. Perform the designated number of reps/holds, then repeat on the opposite side."
