    "instructions": "The stork turns help to isolate the lower body rotation from a fixed upper body and helps promote closed chain hip rotation.   \n \nPlace your golf club in front of you, planted on the floor with both hands grasping the top of the handle. Lift one leg up into a “stork” position. Next, using the lifted leg as a point of reference, rotate the lower body, bringing the knee across midline back and forward while keeping the upper torso still. Perform 3-5 reps"
