    "instructions": "Exercise: D-Walk (Butt Kickers Walking) \n(aka: Butt Kicks Walk, Heel to Glute March, or Hamstring Recovery Walk) \nPurpose: \nThe D-Walk reinforces the backside recovery phase of the running stride by teaching the athlete to: \n \nLift the heel toward the glute using the hamstrings \nMaintain postural control during the movement \nImprove stride mechanics through hamstring awareness \nDevelop coordination and timing for efficient sprinting \n \nIt’s typically included in sprint drills to help athletes understand how to recover the leg properly after push-off, instead of overstriding or letting the leg trail inefficiently. \nTarget Areas: \n \nHamstrings (concentric knee flexion) \nGlutes (postural support) \nHip flexors (rhythmic recovery) \nCalves and ankle complex (if done with forefoot control) \nCore/trunk (to maintain upright posture) \n \nSetup: \n \nFlat surface, 10–15 yards \nComfortable shoes or barefoot (on turf or safe surface) \nIdeal in warm-ups, sprint development, or movement re-education \n \nMovement Pattern: \n \nPosture First: \n \n \nStand tall, spine neutral, ribs stacked over pelvis \nArms bent ~90°, moving naturally with the gait cycle \n \n \nStep and Recover: \n \n \nStep forward and, as your foot leaves the ground, lift your heel toward your glute using the hamstrings \nThe knee stays pointed down — this isn’t a high-knee drill \nKeep your toe dorsiflexed (pulled up), not floppy or pointing down \n \n \nAlternate Legs: \n \n \nSwitch sides smoothly with a walking cadence \nMaintain an even rhythm and upright posture the entire time \n \nReps & Sets: \n \n2–3 sets of 10–15 yards \nCan be done slowly for motor control, or slightly faster for rhythm \n \nKey Coaching Cues: \n \n“Heel to glute, knee stays down.” \n“Pull your foot up — don’t swing it back.” \n“Stay tall, soft landing.” \n“Toes up, not floppy.” \n \nCommon Errors to Watch For: \n \nSwinging the foot backward instead of lifting it vertically \nLetting the knee lift (turning it into a skip) \nOverextending the low back — ribs flaring, pelvis tilting \nToes pointing down — losing ankle control and weakening foot strike mechanics \nBouncing vertically — movement should be smooth and low to the ground \n \nWhy It’s Important: \n \nTrains the backside mechanics of running that are often neglected \nReinforces hamstring coordination and recovery timing \nPrepares athletes for drills like C-Runs, bounding, and full-speed sprints \nGreat for return-to-sport rehab, especially for hamstring or hip injuries \n \nWhen to Use: \n \nAs part of a sprint mechanics warm-up \nIn a running form re-education program \nWithin a hamstring rehab protocol \nPaired with A/B/C drills for a complete sprint stride breakdown \n \nProgressions: \n \nButt kicker skips \nC-Walk and C-Run \nAdd band resistance around the ankles or thighs \nPair with wall hip extension drills or eccentric hamstring strength work"
